INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Schulungsplanung ohne Zielgruppe möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Zielgruppe definiert Inhalte"}, {"text": "Ja", "correct": false, "because": "Fehlende Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element priorisiere ich bei der Schulungsplanung?', 3, '[{"text": "Lernziele", "correct": true, "because": "Definiert Erfolg"}, {"text": "Raumgröße", "correct": false, "because": "Sekundär"}, {"text": "Kaffeepausen", "correct": false, "because": "Nice-to-have"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden eignen sich für Admin-Schulungen?', 5, '[{"text": "Hands-on-Übungen", "correct": true, "because": "Praxisnah"}, {"text": "Live-Demos", "correct": true, "because": "Visuelle Unterstützung"}, {"text": "Reine Theorie", "correct": false, "because": "Zu abstrakt"}, {"text": "Quizspiele", "correct": false, "because": "Weniger tiefgehend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungen brauchen Zeitpläne. b) Endnutzer verstehen alles intuitiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft unrealistisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer Schulung?', 4, '[{"text": "Teilnehmerlevel", "correct": false, "because": "Entscheidet Inhalt"}, {"text": "Technische Ausstattung", "correct": false, "because": "Praxisrelevant"}, {"text": "Farbe der Stifte", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungen immer Präsenz sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Online möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für interaktive Schulungen?', 3, '[{"text": "Zoom mit Breakout-Räumen", "correct": true, "because": "Fördert Gruppenarbeit"}, {"text": "PowerPoint allein", "correct": false, "because": "Wenig Interaktion"}, {"text": "E-Mail", "correct": false, "because": "Kein Echtzeitmedium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Schulung effektiv?', 5, '[{"text": "Praxisbezug", "correct": true, "because": "Verstärkt Anwendung"}, {"text": "Feedbackrunden", "correct": true, "because": "Verbessert Verständnis"}, {"text": "Lange Vorträge", "correct": false, "because": "Ermüdend"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Qualitätsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Schulungen sind nur für Neulinge. b) Admins brauchen keine Updates. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Alle profitieren, Updates nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht absolut"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Endnutzer-Schulung?', 4, '[{"text": "Verständliche Sprache", "correct": false, "because": "Kern der Kommunikation"}, {"text": "Beispiele", "correct": false, "because": "Veranschaulicht"}, {"text": "Kernel-Details", "correct": true, "because": "Zu technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Schulungen ohne Evaluation sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Erfolg unklar"}, {"text": "Ja", "correct": false, "because": "Fehlende Rückmeldung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte sind für Admins entscheidend?', 4, '[{"text": "Troubleshooting", "correct": true, "because": "Praxisrelevant"}, {"text": "Sicherheitsprotokolle", "correct": true, "because": "Schutz gewährleisten"}, {"text": "Marketingstrategien", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schulungen nur einmal nötig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wissen veraltet"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Updates nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Schulung für Endnutzer?', 3, '[{"text": "Bedienbarkeit", "correct": true, "because": "Nutzerfokus"}, {"text": "Technische Tiefe", "correct": false, "because": "Zu komplex"}, {"text": "Code-Beispiele", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungen brauchen Materialien. b) Online ist weniger effektiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) nicht immer"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Schulung?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Bessere Nutzung"}, {"text": "Fehlerreduktion", "correct": true, "because": "Klares Verständnis"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Schulung unwichtig?', 3, '[{"text": "Struktur", "correct": false, "because": "Gibt Orientierung"}, {"text": "Interaktion", "correct": false, "because": "Fördert Lernen"}, {"text": "Traineranzug", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Schulungen die Dokumentation?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Dokumentation bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungen für Admins praxisnah sein müssen?', 2, '[{"text": "Ja", "correct": true, "because": "Anwendung zählt"}, {"text": "Nein", "correct": false, "because": "Theorie allein reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format ist für Schulungen optimal?', 4, '[{"text": "Blended Learning", "correct": true, "because": "Kombiniert Vorteile"}, {"text": "Nur Videos", "correct": false, "because": "Wenig Interaktion"}, {"text": "Nur Texte", "correct": false, "because": "Zu trocken"}]');
